-- Customer capabilities are revocable, scoped to one tenant/customer, expire after 30 days.
create table public.customer_portal_links(id uuid primary key default gen_random_uuid(),estabelecimento_id uuid not null references public.estabelecimento(id),cliente_id uuid not null references public.clientes(id),token uuid not null unique default gen_random_uuid(),expires_at timestamptz not null default now()+interval '30 days',revoked_at timestamptz,created_at timestamptz not null default now());
create table public.portal_requests(estabelecimento_id uuid not null references public.estabelecimento(id),request_key uuid not null,event_id uuid not null references public.agenda_events(id),fingerprint text not null,primary key(estabelecimento_id,request_key));
create table public.pass_reservations(event_id uuid primary key references public.agenda_events(id),pass_id uuid not null references public.customer_passes(id),estabelecimento_id uuid not null references public.estabelecimento(id),request_key uuid not null,fingerprint text not null,created_at timestamptz not null default now(),unique(estabelecimento_id,request_key));
create index pass_reservations_pass on public.pass_reservations(pass_id);
create table public.tenant_integrations(estabelecimento_id uuid primary key references public.estabelecimento(id),whatsapp_enabled boolean not null default false,whatsapp_phone_id text not null default '',whatsapp_template text not null default '',whatsapp_language text not null default 'pt_BR',pix_enabled boolean not null default false,fiscal_enabled boolean not null default false,fiscal_environment text not null default 'homologation' check(fiscal_environment in ('homologation','production')),fiscal_cnpj text not null default '',fiscal_kind text not null default 'nfse' check(fiscal_kind in ('nfse','nfce')),fiscal_profile jsonb not null default '{}',updated_at timestamptz not null default now());
-- Provider credentials never have browser grants. The backend encrypts tokens before storage.
create table private.integration_secrets(estabelecimento_id uuid primary key references public.estabelecimento(id),whatsapp_token text,fiscal_token text);
alter table private.integration_secrets enable row level security;
revoke all on private.integration_secrets from public,anon,authenticated;
grant select,insert,update on private.integration_secrets to service_role;
create table public.whatsapp_deliveries(id uuid primary key default gen_random_uuid(),estabelecimento_id uuid not null references public.estabelecimento(id),event_id uuid not null references public.agenda_events(id),cliente_id uuid not null references public.clientes(id),kind text not null check(kind in ('confirmation','reminder','change')),event_version text not null,status text not null default 'pending' check(status in ('pending','sending','sent','delivered','read','failed','suppressed')),provider_id text unique,error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(event_id,kind,event_version));
create table public.fiscal_documents(id uuid primary key default gen_random_uuid(),estabelecimento_id uuid not null references public.estabelecimento(id),receipt_id uuid not null references public.caixa_itens(id),kind text not null check(kind in ('nfse','nfce')),environment text not null check(environment in ('homologation','production')),status text not null default 'draft' check(status in ('draft','sending','processing','authorized','rejected','cancelled','review')),payload jsonb not null,provider_status text,error text,pdf_url text,xml_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(receipt_id,kind,environment));
do $$declare n text;begin foreach n in array array['customer_portal_links','portal_requests','pass_reservations','tenant_integrations','whatsapp_deliveries','fiscal_documents'] loop
execute format('alter table public.%I enable row level security',n);execute format('revoke all on public.%I from public,anon,authenticated',n);execute format('grant select on public.%I to authenticated',n);execute format('grant all on public.%I to service_role',n);execute format('create policy tenant_owner_read on public.%I for select to authenticated using(public.business_owner(estabelecimento_id))',n);end loop;end $$;
create function private.portal_link(p_tenant uuid,p_customer uuid,p_revoke boolean) returns jsonb language plpgsql security definer set search_path='' as $$declare r public.customer_portal_links;begin
if auth.uid() is null or not public.business_owner(p_tenant) or not exists(select 1 from public.clientes where id=p_customer and estabelecimento_id=p_tenant) then raise exception 'Acesso negado' using errcode='42501';end if;
perform pg_advisory_xact_lock(hashtextextended(p_customer::text,87));
if p_revoke then update public.customer_portal_links set revoked_at=now() where estabelecimento_id=p_tenant and cliente_id=p_customer and revoked_at is null;return jsonb_build_object('revoked',true);end if;
select * into r from public.customer_portal_links where estabelecimento_id=p_tenant and cliente_id=p_customer and revoked_at is null and expires_at>now()+interval '1 day' order by created_at desc limit 1;
if not found then insert into public.customer_portal_links(estabelecimento_id,cliente_id) values(p_tenant,p_customer) returning * into r;end if;
return jsonb_build_object('token',r.token,'expires_at',r.expires_at);end $$;
revoke all on function private.portal_link(uuid,uuid,boolean) from public,anon;
grant execute on function private.portal_link(uuid,uuid,boolean) to authenticated;
create function public.portal_link(p_tenant uuid,p_customer uuid,p_revoke boolean default false) returns jsonb language sql security invoker set search_path='' as $$select private.portal_link(p_tenant,p_customer,p_revoke)$$;
revoke all on function public.portal_link(uuid,uuid,boolean) from public,anon;grant execute on function public.portal_link(uuid,uuid,boolean) to authenticated;
create function public.portal_identity(p_token uuid) returns jsonb language sql security invoker set search_path='' as $$select jsonb_build_object('tenant',l.estabelecimento_id,'customer',l.cliente_id,'name',c.nome,'phone',c.telefone,'slug',e.slug,'business',e.nome) from public.customer_portal_links l join public.clientes c on c.id=l.cliente_id and c.estabelecimento_id=l.estabelecimento_id join public.estabelecimento e on e.id=l.estabelecimento_id where l.token=p_token and l.revoked_at is null and l.expires_at>now() and e.active and greatest(e.trial_ends_at,e.plano_expires_at)>now()$$;
revoke all on function public.portal_identity(uuid) from public,anon,authenticated;grant execute on function public.portal_identity(uuid) to service_role;
create function public.portal_snapshot(p_token uuid) returns jsonb language plpgsql security invoker set search_path='' as $$declare i jsonb;t uuid;c uuid;begin
i:=public.portal_identity(p_token);if i is null then raise exception 'Link inválido ou expirado';end if;t:=(i->>'tenant')::uuid;c:=(i->>'customer')::uuid;
return i||jsonb_build_object('appointments',coalesce((select jsonb_agg(x order by x.start) from(select a.id,a.start,a."end",a.status,a.servico_id as service_id,a.profissional_id as professional_id,s.titulo as service,p.nome as professional,exists(select 1 from public.booking_deposits d where d.event_id=a.id and d.status in ('paid','refund_pending')) as deposit_paid,a.metadata->>'cancel_requested_at' as cancel_requested_at from public.agenda_events a left join public.servicos s on s.id=a.servico_id left join public.profissionais p on p.id=a.profissional_id where a.estabelecimento_id=t and a.cliente_id=c and a.start>now()-interval '30 days' order by a.start limit 100)x),'[]'),
'passes',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'service_id',p.servico_id,'title',p.title,'remaining',p.remaining,'reserved',(select count(*) from public.pass_reservations r join public.agenda_events a on a.id=r.event_id where r.pass_id=p.id and a.status not in ('cancelado','noshow') and not coalesce(a.cobranca_enviada,false)),'expires_at',p.expires_at)) from public.customer_passes p where p.estabelecimento_id=t and p.cliente_id=c and p.status='active' and p.expires_at>now()),'[]'),
'payments',coalesce((select jsonb_agg(x) from(select id,token_publico as token,valor_total,status_caixa,pago_em from public.caixa_itens where estabelecimento_id=t and cliente_id=c and origem<>'resgate' order by created_at desc limit 30)x),'[]'),
'clubs',coalesce((select jsonb_agg(jsonb_build_object('title',title,'token',token,'status',status,'next_due',next_due)) from public.club_contracts where estabelecimento_id=t and cliente_id=c),'[]'));
end $$;
revoke all on function public.portal_snapshot(uuid) from public,anon,authenticated;grant execute on function public.portal_snapshot(uuid) to service_role;
create function public.portal_cancel(p_token uuid,p_event uuid) returns jsonb language plpgsql security invoker set search_path='' as $$declare i jsonb;a public.agenda_events;begin
i:=public.portal_identity(p_token);if i is null then raise exception 'Link inválido ou expirado';end if;
select * into a from public.agenda_events where id=p_event and estabelecimento_id=(i->>'tenant')::uuid and cliente_id=(i->>'customer')::uuid for update;
if not found or a.start<=now()+interval '2 hours' or a.status not in ('pendente','confirmado') then raise exception 'Cancelamento online disponível até 2 horas antes. Entre em contato com o estabelecimento.';end if;
if exists(select 1 from public.booking_deposits where event_id=a.id and status in ('pending','paid','refund_pending')) then update public.agenda_events set metadata=coalesce(metadata,'{}')||jsonb_build_object('cancel_requested_at',now()) where id=a.id;return jsonb_build_object('requested',true);end if;
update public.agenda_events set status='cancelado' where id=a.id;delete from public.pass_reservations where event_id=a.id;return jsonb_build_object('cancelled',true);end $$;
revoke all on function public.portal_cancel(uuid,uuid) from public,anon,authenticated;grant execute on function public.portal_cancel(uuid,uuid) to service_role;
-- Called only after the public booking API has validated duration, hours, professional and availability.
create function public.portal_reserve(p_token uuid,p_data jsonb,p_key uuid,p_pass uuid default null,p_event uuid default null) returns jsonb language plpgsql security invoker set search_path='' as $$declare i jsonb;t uuid;c uuid;p public.customer_passes;a public.agenda_events;prev public.portal_requests;fp text;begin
i:=public.portal_identity(p_token);if i is null then raise exception 'Link inválido ou expirado';end if;t:=(i->>'tenant')::uuid;c:=(i->>'customer')::uuid;
if t<>(p_data->>'estabelecimento_id')::uuid or p_key is null then raise exception 'Reserva inválida';end if;
fp:=md5(p_data::text||coalesce(p_pass::text,'')||coalesce(p_event::text,''));
perform pg_advisory_xact_lock(hashtextextended(t::text||p_key::text,91));
select * into prev from public.portal_requests where estabelecimento_id=t and request_key=p_key;
if found then if prev.fingerprint<>fp then raise exception 'Tentativa corresponde a outra reserva';end if;select * into a from public.agenda_events where id=prev.event_id;return jsonb_build_object('success',true,'event',to_jsonb(a));end if;
if p_event is not null then select * into a from public.agenda_events where id=p_event and estabelecimento_id=t and cliente_id=c for update;if not found or a.servico_id is distinct from (p_data->>'servico_id')::uuid or a.start<=now()+interval '2 hours' or a.status not in ('pendente','confirmado') or a.cobranca_enviada then raise exception 'Remarcação indisponível';end if;
if exists(select 1 from public.booking_deposits where event_id=a.id and status in ('pending','paid','refund_pending')) then raise exception 'Entre em contato para remarcar uma reserva com sinal';end if;
select pass_id into p_pass from public.pass_reservations where event_id=a.id;
end if;
if p_pass is not null then
select * into p from public.customer_passes where id=p_pass and estabelecimento_id=t and cliente_id=c for update;
if not found or p.status<>'active' or p.expires_at<=(p_data->>'end')::timestamptz or p.servico_id<>(p_data->>'servico_id')::uuid or p.remaining<1 or p.remaining<=(select count(*) from public.pass_reservations r join public.agenda_events x on x.id=r.event_id where r.pass_id=p.id and r.event_id is distinct from p_event and x.status not in ('cancelado','noshow') and not coalesce(x.cobranca_enviada,false)) then raise exception 'Saldo indisponível para este serviço ou data';end if;
elsif coalesce((select deposit_percent from public.business_settings where estabelecimento_id=t),0)>0 then raise exception 'Selecione um pacote com saldo ou reserve pela agenda pública com sinal';end if;
if p_event is null then
insert into public.agenda_events(estabelecimento_id,cliente_id,servico_id,profissional_id,title,start,"end",status,metadata) values(t,c,(p_data->>'servico_id')::uuid,nullif(p_data->>'profissional_id','')::uuid,coalesce(i->>'name','Cliente')||' — atendimento',(p_data->>'start')::timestamptz,(p_data->>'end')::timestamptz,case when coalesce((select approval_required from public.business_settings where estabelecimento_id=t),false) then 'pendente' else 'confirmado' end,coalesce(p_data->'metadata','{}')||jsonb_build_object('origin','customer_portal')) returning * into a;
else update public.agenda_events set start=(p_data->>'start')::timestamptz,"end"=(p_data->>'end')::timestamptz,profissional_id=nullif(p_data->>'profissional_id','')::uuid where id=p_event returning * into a;delete from public.pass_reservations where event_id=p_event;end if;
if p_pass is not null then insert into public.pass_reservations(event_id,pass_id,estabelecimento_id,request_key,fingerprint) values(a.id,p_pass,t,p_key,fp);end if;
insert into public.portal_requests(estabelecimento_id,request_key,event_id,fingerprint) values(t,p_key,a.id,fp);
return jsonb_build_object('success',true,'event',jsonb_build_object('id',a.id,'start',a.start,'end',a."end",'status',a.status),'prepaid',p_pass is not null);end $$;
revoke all on function public.portal_reserve(uuid,jsonb,uuid,uuid,uuid) from public,anon,authenticated;grant execute on function public.portal_reserve(uuid,jsonb,uuid,uuid,uuid) to service_role;
-- Release a reservation just before a paid redemption is created. The existing redemption transaction owns the pass row lock.
create function private.release_pass_reservation() returns trigger language plpgsql security definer set search_path='' as $$begin
if new.origem='resgate' then delete from public.pass_reservations where event_id=new.agenda_event_id and estabelecimento_id=new.estabelecimento_id and exists(select 1 from public.agenda_events a where a.id=new.agenda_event_id and a.estabelecimento_id=new.estabelecimento_id and a.cliente_id=new.cliente_id);end if;return new;end $$;
revoke all on function private.release_pass_reservation() from public,anon,authenticated;
create trigger release_pass_reservation before insert on public.caixa_itens for each row execute function private.release_pass_reservation();
create function private.guard_reserved_pass() returns trigger language plpgsql security definer set search_path='' as $$begin
if new.remaining<old.remaining and new.remaining<(select count(*) from public.pass_reservations r join public.agenda_events a on a.id=r.event_id where r.pass_id=new.id and a.status not in ('cancelado','noshow') and not coalesce(a.cobranca_enviada,false)) then raise exception 'Há sessões reservadas. Use o pacote no atendimento reservado ou libere a reserva.';end if;
if new.status in ('refund_pending','cancelled') and old.status='active' and exists(select 1 from public.pass_reservations r join public.agenda_events a on a.id=r.event_id where r.pass_id=new.id and a.status not in ('cancelado','noshow') and not coalesce(a.cobranca_enviada,false)) then raise exception 'Cancele as reservas do pacote antes de solicitar estorno';end if;return new;end $$;
revoke all on function private.guard_reserved_pass() from public,anon,authenticated;create trigger guard_reserved_pass before update on public.customer_passes for each row execute function private.guard_reserved_pass();
create function public.prepare_whatsapp_notifications() returns integer language plpgsql security invoker set search_path='' as $$declare n integer;begin
insert into public.whatsapp_deliveries(estabelecimento_id,event_id,cliente_id,kind,event_version)
select a.estabelecimento_id,a.id,a.cliente_id,case when a.start<now()+interval '25 hours' and a.start>now()+interval '23 hours' then 'reminder' else 'confirmation' end,a.start::text||':'||a.status from public.agenda_events a join public.tenant_integrations i on i.estabelecimento_id=a.estabelecimento_id and i.whatsapp_enabled join public.estabelecimento e on e.id=a.estabelecimento_id and e.active and greatest(e.trial_ends_at,e.plano_expires_at)>now() join public.client_contact_preferences p on p.estabelecimento_id=a.estabelecimento_id and p.cliente_id=a.cliente_id and p.channel='whatsapp' and p.consent where not exists(select 1 from public.whatsapp_deliveries w where w.event_id=a.id and w.kind=case when a.start<now()+interval '25 hours' and a.start>now()+interval '23 hours' then 'reminder' else 'confirmation' end and w.event_version=a.start::text||':'||a.status) and a.start>now()+interval '30 minutes' and a.start<now()+interval '180 days' and a.status in ('confirmado','pendente') and (a.created_at>now()-interval '30 minutes' or (a.start<now()+interval '25 hours' and a.start>now()+interval '23 hours')) limit 200 on conflict do nothing;get diagnostics n=row_count;return n;end $$;
revoke all on function public.prepare_whatsapp_notifications() from public,anon,authenticated;grant execute on function public.prepare_whatsapp_notifications() to service_role;
create function private.queue_whatsapp_change() returns trigger language plpgsql security definer set search_path='' as $$begin
if (new.start is distinct from old.start or new.status is distinct from old.status) and new.cliente_id is not null and exists(select 1 from public.tenant_integrations where estabelecimento_id=new.estabelecimento_id and whatsapp_enabled) then update public.whatsapp_deliveries set status='suppressed',updated_at=now() where event_id=new.id and status='pending';insert into public.whatsapp_deliveries(estabelecimento_id,event_id,cliente_id,kind,event_version) values(new.estabelecimento_id,new.id,new.cliente_id,'change',new.start::text||':'||new.status||':'||clock_timestamp()::text) on conflict do nothing;end if;return new;end $$;
revoke all on function private.queue_whatsapp_change() from public,anon,authenticated;create trigger queue_whatsapp_change after update of start,status on public.agenda_events for each row execute function private.queue_whatsapp_change();
notify pgrst,'reload schema';

create function public.integration_secret(p_tenant uuid,p_patch jsonb default null) returns jsonb language plpgsql security invoker set search_path='' as $$declare r private.integration_secrets;begin
if p_patch is not null then insert into private.integration_secrets(estabelecimento_id,whatsapp_token,fiscal_token) values(p_tenant,p_patch->>'whatsapp_token',p_patch->>'fiscal_token') on conflict(estabelecimento_id) do update set whatsapp_token=coalesce(excluded.whatsapp_token,integration_secrets.whatsapp_token),fiscal_token=coalesce(excluded.fiscal_token,integration_secrets.fiscal_token);end if;
select * into r from private.integration_secrets where estabelecimento_id=p_tenant;return jsonb_build_object('whatsapp_token',r.whatsapp_token,'fiscal_token',r.fiscal_token);end $$;
revoke all on function public.integration_secret(uuid,jsonb) from public,anon,authenticated;grant execute on function public.integration_secret(uuid,jsonb) to service_role;
create index whatsapp_pending on public.whatsapp_deliveries(created_at) where status='pending';
create index fiscal_processing on public.fiscal_documents(updated_at) where status in ('sending','processing','review');
notify pgrst,'reload schema';

create unique index integration_whatsapp_phone on public.tenant_integrations(whatsapp_phone_id) where whatsapp_phone_id<>'';
-- A held prepaid service must not be charged again through the regular POS.
create function private.guard_reserved_checkout() returns trigger language plpgsql security definer set search_path='' as $$begin
if new.agenda_event_id is not null and new.origem is distinct from 'resgate' and exists(select 1 from public.pass_reservations where event_id=new.agenda_event_id) then raise exception 'Este atendimento tem uma sessão reservada. Use o pacote ou cancele a reserva antes de cobrar.';end if;return new;end $$;
revoke all on function private.guard_reserved_checkout() from public,anon,authenticated;create trigger guard_reserved_checkout before insert on public.caixa_itens for each row execute function private.guard_reserved_checkout();
create function public.whatsapp_unsubscribe(p_tenant uuid,p_phone text) returns void language plpgsql security invoker set search_path='' as $$begin
insert into public.client_contact_preferences(estabelecimento_id,cliente_id,channel,consent,evidence) select p_tenant,c.id,'whatsapp',false,'SAIR recebido no WhatsApp oficial' from public.clientes c where c.estabelecimento_id=p_tenant and regexp_replace(c.telefone,'\D','','g') in (p_phone,substring(p_phone from 3)) on conflict(estabelecimento_id,cliente_id,channel) do update set consent=false,evidence=excluded.evidence,updated_at=now();
update public.whatsapp_deliveries set status='suppressed',updated_at=now() where estabelecimento_id=p_tenant and status='pending' and cliente_id in(select cliente_id from public.client_contact_preferences where estabelecimento_id=p_tenant and channel='whatsapp' and not consent);end $$;
revoke all on function public.whatsapp_unsubscribe(uuid,text) from public,anon,authenticated;grant execute on function public.whatsapp_unsubscribe(uuid,text) to service_role;
notify pgrst,'reload schema';

create index portal_links_customer on public.customer_portal_links(estabelecimento_id,cliente_id,created_at desc);
create index whatsapp_tenant_recent on public.whatsapp_deliveries(estabelecimento_id,created_at desc);
create index fiscal_tenant_recent on public.fiscal_documents(estabelecimento_id,created_at desc);
drop policy tenant_owner_read on public.pass_reservations;
create policy cash_reservation_read on public.pass_reservations for select to authenticated using(public.can_operate_cash(estabelecimento_id));
