-- Preserve delivery callbacks that arrive before the send response is persisted.
create table private.whatsapp_statuses(estabelecimento_id uuid not null references public.estabelecimento(id),provider_id text not null,status text not null check(status in ('sent','delivered','read','failed')),updated_at timestamptz not null default now(),primary key(estabelecimento_id,provider_id));
alter table private.whatsapp_statuses enable row level security;revoke all on private.whatsapp_statuses from public,anon,authenticated;grant all on private.whatsapp_statuses to service_role;
create function public.whatsapp_status(p_phone text,p_id text,p_status text) returns void language plpgsql security invoker set search_path='' as $$declare t uuid;old_rank integer;new_rank integer;st text;begin
if p_status not in ('sent','delivered','read','failed') or p_id is null or length(p_id)>500 then return;end if;
select estabelecimento_id into t from public.tenant_integrations where whatsapp_phone_id=p_phone;if t is null then return;end if;
perform pg_advisory_xact_lock(hashtextextended(t::text||p_id,117));
select status into st from private.whatsapp_statuses where estabelecimento_id=t and provider_id=p_id;
old_rank:=case st when 'sent' then 1 when 'failed' then 2 when 'delivered' then 3 when 'read' then 4 else 0 end;new_rank:=case p_status when 'sent' then 1 when 'failed' then 2 when 'delivered' then 3 when 'read' then 4 end;
if new_rank>old_rank then insert into private.whatsapp_statuses(estabelecimento_id,provider_id,status) values(t,p_id,p_status) on conflict(estabelecimento_id,provider_id) do update set status=excluded.status,updated_at=now();st:=p_status;end if;
update public.whatsapp_deliveries set status=st,error=case when st='failed' then 'O WhatsApp recusou a entrega. Confira o número e o modelo aprovado.' else null end,updated_at=now() where estabelecimento_id=t and provider_id=p_id;
end $$;
revoke all on function public.whatsapp_status(text,text,text) from public,anon,authenticated;grant execute on function public.whatsapp_status(text,text,text) to service_role;
notify pgrst,'reload schema';
